      'masses':r'\bm_i\b|\bm_j\b|m₁|mass (triple|case|order)|c_ij|masses',
      'E':r'\bE\+U\b|\(E\+U\)|energy E\b|ℳ_\{E,L\}|E < 0|at energy E',
      'L':r'angular momentum|ℳ_\{E,L\}|\bL\)',
      'G':r'\bG\b(?!\.)|gravitational|Newton'}
children={o:[] for o in objs}
for o in objs:
    for d in objs[o]['deps']: children[d].append(o)
def desc(s):
    out=set(s); st=list(s)
    while st:
        x=st.pop()
        for c in children[x]:
            if c not in out: out.add(c); st.append(c)
