import re,unicodedata
def norm(s): return unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()
C=open('The_Method_1_6___Mathematical_Compendium-2.md',encoding='utf-8').read()
bib=re.findall(r'^\| (\d{4}) \| (.+?) \| (.*?) \|$',C[C.index('# VII · THE BIBLIOGRAPHY'):C.index('# THE MATHEMATICS OF THE LÖWDIN WORK')],re.M)
print(len(bib),'works in Math bibliography')
M=open('The_Method_1_6-2.md',encoding='utf-8').read(); refs=norm(M[M.index('\n# References'):])
L=norm(open('THE-LOWDIN-SOLUTION-2.md',encoding='utf-8').read()); B=norm(open('The_Three_Body_Problem_for_Unknown_Masses_Lach-2.md',encoding='utf-8').read())
missing=[]
for y,w,objs in bib:
    names=[n.strip() for n in re.split(r'\s*(?:&|and|,)\s*',norm(w)) if n.strip()]
    first=names[0].split()[-1] if names else ''
    first=re.sub(r'[^a-z]','',first)
    ok=lambda txt: first and first in txt and y in txt and re.search(first+r'.{0,120}'+y+r'|'+y+r'.{0,120}'+first,txt,re.S)
    where=[]
    if ok(refs): where.append('main')
    if ok(L): where.append('Löwdin paper')
    if ok(B): where.append('3B paper')
    if not where: missing.append((y,w,objs))
print(len(missing),'not found in main References or either paper:')
for y,w,o in missing: print(f"  {y} {w} — {o}")
